mapper.update:
update user_account
set last_login_at = now(),
    updated_at = now(),
    version = version + 1
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and id = #{userId}

update user_session
set revoked = true
where tenant_id = #{tenantId}
  and app_id = #{appId}
  and user_id = #{userId}
  and revoked = false
  and expired_at > now()

